# Check for ALL L-shaped components, not just Type A/B
height, width = len(inp), len(inp[0])
visited = set()
all_components = []

for r in range(height):
    for c in range(width):
        if inp[r][c] != 0 and (r, c) not in visited:
            component = []
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in visited or inp[cr][cc] == 0:
                    continue
                visited.add((cr, cc))
                component.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if inp[nr][nc] != 0 and (nr, nc) not in visited:
                            stack.append((nr, nc))
            if len(component) >= 3:
                all_components.append(component)

print(f"Total L-components (len >= 3): {len(all_components)}")
print()

